import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.76ZGnlPi.js";const m=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog/index.md","filePath":"changelog/index.md"}'),o={name:"changelog/index.md"};function r(s,e,l,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>One entry per week (Monday to Sunday), newest first. An entry lists what the week changed for a client of the API: the web frontend, the mobile app, the admin panel and API partners. From then on, the routes it names keep their shape; a breaking change to one of them is written here as <strong>Breaking:</strong> with its reason.</p><ul><li>Paths leave out the <code>/api/v1</code> prefix.</li><li>A line that ends with <em>Staging only</em> is on staging and not yet in production. The marker is removed when the release reaches production.</li><li>Internal work (tests, deployment, logging, refactors) is not listed.</li></ul><h2 id="_19-to-25-october-2026" tabindex="-1">19 to 25 October 2026 <a class="header-anchor" href="#_19-to-25-october-2026" aria-label="Permalink to &quot;19 to 25 October 2026&quot;">​</a></h2><ul><li>New public <code>POST /landing/search</code> prices the routes an admin sets, for a search page that takes orders over WhatsApp. Admins manage those prices under <code>/admin/landing-route-price</code>; <code>applyToReverse</code> writes the return direction too. See <a href="/ahlaan-train-docs/guest/landing-search/">Landing search</a> and <a href="/ahlaan-train-docs/admin/landing-route-price/">Landing route prices</a>.</li><li><strong>Breaking:</strong> <code>POST /landing/search</code> requires <code>passengerQuantities</code> (<code>{ adults, children, infants }</code>, the <code>ota/search</code> shape) and answers 400 without it. Each class now carries <code>ptcFareBreakdown</code>, and the response echoes <code>passengers</code>. Why: the search prices a passenger group instead of a single seat. See <a href="/ahlaan-train-docs/guest/landing-search/">Landing search</a>.</li><li>Admins set the child and infant share of the adult landing price under <code>/admin/landing-pricing-config</code>. With no setting, a child pays 70% and an infant 0%. See <a href="/ahlaan-train-docs/admin/landing-route-price/">Landing route prices</a>.</li><li>The landing configuration chooses where its SAR to IDR rate comes from: <code>idrRateSource</code> is <code>BANK_RATE</code> (with <code>idrRateBankCode</code> and <code>idrRateType</code>) or <code>GLOBAL_RATE</code>. The rate is rounded up to a whole rupiah.</li><li>New public <code>GET /landing/exchange-rate</code> returns the rate the landing search uses: <code>currency</code>, <code>IDR</code>, <code>source</code>, <code>bankCode</code>, <code>rateType</code> and <code>asOf</code>. See <a href="/ahlaan-train-docs/guest/landing-search/">Landing search</a>.</li><li>New admin <code>GET /admin/bank-exchange-rates</code> and <code>GET /admin/bank-exchange-rates/series</code> list the recorded bank rates. On <code>GET /admin/bank-exchange-rates</code>, <code>from</code> and <code>to</code> (ISO date-time with time zone) select the rates in effect in that window. See <a href="/ahlaan-train-docs/admin/bank-exchange-rate/">Bank exchange rates</a>.</li><li>New <code>POST /scraper/bank-exchange-rates</code> (API key) records the bank rates pushed by the rate scraper.</li><li>The automatic SAR rate can follow a bank series: <code>GET</code> and <code>PATCH /admin/exchange-rate/settings</code> take <code>bankCode</code> and <code>bankRateType</code>, with the new source <code>BANK_RATE</code>. See <a href="/ahlaan-train-docs/admin/exchange-rate/">Exchange rate</a>.</li><li><code>PATCH /admin/exchange-rate/settings</code> with an invalid <code>timeZone</code> now answers with code <code>INPUT_VALIDATION</code> instead of <code>UNCODED</code>, and saves nothing. See <a href="/ahlaan-train-docs/admin/exchange-rate/">Exchange rate</a>.</li><li>Search and availability results served from cache are priced at the current exchange rate.</li><li><code>POST /admin/ota/cache/refresh</code> also clears cached availability. See <a href="/ahlaan-train-docs/admin/ota/cache-status.html">Cache status</a>.</li></ul><h2 id="_12-to-18-october-2026" tabindex="-1">12 to 18 October 2026 <a class="header-anchor" href="#_12-to-18-october-2026" aria-label="Permalink to &quot;12 to 18 October 2026&quot;">​</a></h2><ul><li>The admin custom-booking list returns <code>ticketUploadedAt</code>, the time the first ticket file arrived, and accepts it as a <code>sortBy</code> value. See <a href="/ahlaan-train-docs/admin/custom-booking/">Custom booking (admin)</a>.</li><li>The admin custom-booking list filters by <code>capitalPriceMissing</code> and counts those rows in <code>meta.summary.capitalPriceMissingCount</code>. Both need the <code>custom-bookings:read-capital-markup</code> permission; without it the filter answers 403. See <a href="/ahlaan-train-docs/admin/custom-booking/">Custom booking (admin)</a>.</li><li>When the cache fails, cached rule reads fall back to the database and admin writes still succeed.</li><li>In forced manual exchange-rate mode, the scheduled bank-rate scrape no longer runs. See <a href="/ahlaan-train-docs/admin/exchange-rate/">Exchange rate</a>.</li></ul><h2 id="_5-to-11-october-2026" tabindex="-1">5 to 11 October 2026 <a class="header-anchor" href="#_5-to-11-october-2026" aria-label="Permalink to &quot;5 to 11 October 2026&quot;">​</a></h2><ul><li>Once an invoice has a payment on it (<code>totalPaid</code> above 0), every customer payment on that invoice is refused with 400, <code>available-gateways</code> returns no gateway, and <code>payment-options</code> is empty. See <a href="/ahlaan-train-docs/customer/payment-gateways-by-currency/">Payment gateways by currency</a>.</li><li>After 5 wrong OTP codes, the codes still open stop working; the user requests a new one. A repeated Mitra registration request sends a new code. See <a href="/ahlaan-train-docs/customer/register-login/">Register and login</a>.</li><li>Admin reports cut days on the app time zone (Asia/Riyadh), so daily figures can differ from before: invoice, payment, refund, wallet, OTA booking and organization reports. See <a href="/ahlaan-train-docs/admin/reports/">Reports</a>.</li><li>Organization transaction and wallet reports return the right rows for an organization without a wallet. See <a href="/ahlaan-train-docs/admin/reports/organization.html">Organization reports</a>.</li><li>The OTA report applies <code>route</code> to the previous period too. See <a href="/ahlaan-train-docs/admin/reports/">Reports</a>.</li><li><code>GET /admin/custom-booking/:id</code> and <code>POST /admin/custom-booking/:id/ticket</code> report ordered ticket totals: <code>totalTicketsExpected</code>, <code>totalTicketsUploaded</code>, <code>totalTicketsMissing</code> and the matching <code>totalInfantTickets…</code> fields. See <a href="/ahlaan-train-docs/admin/custom-booking/">Custom booking (admin)</a>.</li><li>Shortfall amounts round half-up. See <a href="/ahlaan-train-docs/admin/shortfall-settlements/">Shortfall settlements</a>.</li></ul><h2 id="_28-september-to-4-october-2026" tabindex="-1">28 September to 4 October 2026 <a class="header-anchor" href="#_28-september-to-4-october-2026" aria-label="Permalink to &quot;28 September to 4 October 2026&quot;">​</a></h2><ul><li><code>POST /invoice/:id/generate-payment</code> runs its checks before it reuses an open link. A Xendit link is reused on every IDR invoice. Two clicks at the same time get one link, or 409 after 20 seconds. See <a href="/ahlaan-train-docs/customer/payment-gateways-by-currency/">Payment gateways by currency</a>.</li><li><code>GET /invoice/:id/available-gateways</code> returns <code>displayText</code> per gateway: a title and description in Indonesian, English and Arabic. Admins edit it with <code>GET</code> and <code>PATCH /admin/payment-gateway/:code/display-text</code>. See <a href="/ahlaan-train-docs/admin/payment-gateway/">Payment gateway</a>.</li><li><strong>Breaking:</strong> <code>POST /ota/book</code> creates the invoice in IDR. Its <code>currency</code> field is still accepted but deprecated, and no longer sets the invoice currency; BlockSeat invoices are IDR too. Choosing the other gateway at payment cancels the old link: 400 if it was already paid, 409 if it was paid for a different amount, 503 if the cancel cannot be confirmed. Why: the customer picks the currency by picking the gateway, Xendit in IDR or Moyasar in SAR. See <a href="/ahlaan-train-docs/customer/payment-gateways-by-currency/">Payment gateways by currency</a>.</li><li>Each <code>availableGateways</code> entry carries <code>currency</code> and <code>amount</code>. Optional <code>?currency=IDR|SAR|USD</code> filters the list; any other value answers 400.</li></ul><h2 id="_21-to-27-september-2026" tabindex="-1">21 to 27 September 2026 <a class="header-anchor" href="#_21-to-27-september-2026" aria-label="Permalink to &quot;21 to 27 September 2026&quot;">​</a></h2><ul><li><code>GET /ota/routes</code> serves the last good list (up to 7 days old) when the carrier fails. With nothing cached and a carrier failure in the last 60 seconds, it fails fast with 502. See <a href="/ahlaan-train-docs/customer/ota/">OTA</a>.</li><li>New public <code>GET /ota/carrier-health</code> for uptime monitors: 200 or 503, with a verdict for each side (<code>rest</code> and <code>ota</code>). <code>?check=rest</code> or <code>?check=ota</code> checks one side; any other value answers 400. Limited to 30 calls a minute.</li><li>Xendit payments settle even when the webhook does not arrive. A payment that arrives after the carrier deadline leaves the booking <code>EXPIRED</code>.</li><li>New gateway Moyasar: a hosted payment page for SAR invoices, added switched off. It lists <code>CARDS</code> in <code>supportedMethods</code>. See <a href="/ahlaan-train-docs/admin/payment-gateway/">Payment gateway</a>.</li><li><strong>Breaking:</strong> Xendit and Moyasar payments return <code>paymentMethod: &quot;HOSTED_CHECKOUT&quot;</code>; Xendit returned <code>BANK_TRANSFER</code> before. New <code>paidMethod</code> and <code>paidChannel</code> say what the customer used. <code>BANK_TRANSFER</code> (Xendit) and <code>CARD</code> (Moyasar) are still accepted as input on generate-payment and wallet top-up. Why: the customer picks how to pay on the gateway&#39;s own page, so the stored method was wrong for QRIS, e-wallets and the rest.</li><li>SAR and USD booking invoices convert at the right rate, and their <code>exchangeRateId</code> is null.</li></ul><h2 id="_14-to-20-september-2026" tabindex="-1">14 to 20 September 2026 <a class="header-anchor" href="#_14-to-20-september-2026" aria-label="Permalink to &quot;14 to 20 September 2026&quot;">​</a></h2><ul><li>Admins manage a separate bank webhook signing secret for each partner. See <a href="/ahlaan-train-docs/admin/partners/">Partners</a>.</li><li>Partner GROUP orders: passenger details go to the carrier only once it holds the names, and a re-submission reuses the stored passenger references.</li><li>An hourly job fills a missing supplier cost from the carrier and records it in the supplier ledger. See <a href="/ahlaan-train-docs/admin/supplier-ledger/">Supplier ledger</a>.</li></ul><h2 id="_7-to-13-september-2026" tabindex="-1">7 to 13 September 2026 <a class="header-anchor" href="#_7-to-13-september-2026" aria-label="Permalink to &quot;7 to 13 September 2026&quot;">​</a></h2><ul><li>New admin supplier ledger tracks and reconciles our balance at the carrier. See <a href="/ahlaan-train-docs/admin/supplier-ledger/">Supplier ledger</a>.</li><li>New <code>PATCH /ota/bookings/:id/seats</code> moves several passengers in one call. Seat selection is refused when the carrier account has no seat map, and the response says why it is off. Unreachable seats are refused up front, a wrong-class refusal gets its own error, and the carrier&#39;s seat status is shown. See <a href="/ahlaan-train-docs/customer/seat-selection/">Seat selection</a>.</li><li>The booking detail shows prices per passenger type for each leg. See <a href="/ahlaan-train-docs/customer/booking-management/">Booking management</a>.</li><li>A payment that an invoice cannot take is refused and no longer offered. Admins see invoices that link to nothing; creating an invoice by hand is behind a switch. See <a href="/ahlaan-train-docs/admin/invoice/">Invoice</a>.</li><li>A B2B user without an organization sees only their own invoices.</li><li>An act-as-customer session can read the invoice list and payment status. See <a href="/ahlaan-train-docs/admin/impersonation/">Impersonation</a>.</li><li>The return leg&#39;s ticket link carries its own coupon number.</li><li>Partners: a previous handoff key is accepted during a rotation window, and each partner API key carries <code>allowedNetworks</code>, managed by admins. See <a href="/ahlaan-train-docs/admin/partners/">Partners</a>.</li></ul><h2 id="_31-august-to-6-september-2026" tabindex="-1">31 August to 6 September 2026 <a class="header-anchor" href="#_31-august-to-6-september-2026" aria-label="Permalink to &quot;31 August to 6 September 2026&quot;">​</a></h2><ul><li>New seat map and seat change: <code>GET /ota/bookings/:id/seat-map</code> and <code>PATCH /ota/bookings/:id/seat</code>. The booking detail reports the new seat. A booking too close to departure says why it has no seat window. Coach class and passenger type use the shared enums. See <a href="/ahlaan-train-docs/customer/seat-selection/">Seat selection</a> and <a href="/ahlaan-train-docs/admin/seat-management/">Seat management</a>.</li><li>The admin booking list and detail show refund rows of any method and the cancel outcome. See <a href="/ahlaan-train-docs/admin/booking-management/">Booking management (admin)</a>.</li><li>Refund and payment status filters on admin lists refuse unknown values with 400.</li><li>Admins get a work list of unpaid refunds and can re-run a refund job; the refund report counts only money paid. See <a href="/ahlaan-train-docs/admin/refunds/">Refunds (admin)</a>.</li><li>The automatic cancellation refund no longer adds wallet balance.</li><li>An admin retry of a <code>FAILED</code> booking now works.</li><li>A partner cancelling a paid order queues its refund. New partner credit ledger. See <a href="/ahlaan-train-docs/admin/partners/">Partners</a>.</li></ul><h2 id="_24-to-30-august-2026" tabindex="-1">24 to 30 August 2026 <a class="header-anchor" href="#_24-to-30-august-2026" aria-label="Permalink to &quot;24 to 30 August 2026&quot;">​</a></h2><ul><li>Admins record infant ticket delivery per leg; a missing infant ticket no longer counts as a seated ticket. See <a href="/ahlaan-train-docs/admin/custom-booking/">Custom booking (admin)</a>.</li><li><code>returnDate</code> is null on a custom booking that is not <code>ROUND_TRIP</code>.</li><li>A partner&#39;s GROUP passenger names are sent to the carrier.</li></ul><h2 id="_17-to-23-august-2026" tabindex="-1">17 to 23 August 2026 <a class="header-anchor" href="#_17-to-23-august-2026" aria-label="Permalink to &quot;17 to 23 August 2026&quot;">​</a></h2><ul><li>Reseller commission: monthly statement and partner-side list filters; the return leg shows on every commission surface; commission and payout routes carry partner identity. The read permission is split, so a payout role sees the work list but not the partner detail. See <a href="/ahlaan-train-docs/customer/reseller-commission/">Reseller commission</a> and <a href="/ahlaan-train-docs/admin/reseller-commission/">Reseller commission (admin)</a>.</li><li>Custom booking ticket files are stored per leg and must be PDF. See <a href="/ahlaan-train-docs/admin/custom-booking/">Custom booking (admin)</a>.</li><li>On the invoice list, an <code>endDate</code> without a time covers the whole UTC day. See <a href="/ahlaan-train-docs/admin/invoice/">Invoice</a>.</li><li>Mitra registration approval needs two-step payment verification. See <a href="/ahlaan-train-docs/admin/mitra-registrations/">Mitra registrations</a>.</li><li>Admin lists: settlement reports filter by date and show verifier names and proof links; the custom-booking list shows ticket counts and partner identity; invoices and shortfall settlements filter by total passengers and settlement date; shortfall settlements show and filter by partner identity. See <a href="/ahlaan-train-docs/admin/shortfall-settlements/">Shortfall settlements</a>.</li><li>The email footer shows the new phone number with a WhatsApp link.</li></ul><h2 id="_10-to-16-august-2026" tabindex="-1">10 to 16 August 2026 <a class="header-anchor" href="#_10-to-16-august-2026" aria-label="Permalink to &quot;10 to 16 August 2026&quot;">​</a></h2><ul><li>New RESELLER pricing tier with a per-passenger commission and payout: separate ECONOMY and BUSINESS rates priced per leg; payout detail, commission drill-down, transfer proof and per-partner totals; a payout work list with filters, preview and a required destination account; one finance admin records a payout in a single call; the payout list filters by earner. See <a href="/ahlaan-train-docs/customer/reseller-commission/">Reseller commission</a> and <a href="/ahlaan-train-docs/admin/reseller-commission/">Reseller commission (admin)</a>.</li><li>The Mitra registration fee is set by admins, with a limited promo. See <a href="/ahlaan-train-docs/admin/mitra-registration-fee/">Mitra registration fee</a>.</li><li>Shortfall: ticket counts are taken at ticket upload and amounts at settlement, per leg; the settlement rate comes from the booking when not given; admins read the bank transfer proof, and the booking detail shows it. See <a href="/ahlaan-train-docs/admin/shortfall-settlements/">Shortfall settlements</a>.</li><li>The custom-booking money permission is split into selling prices and cost basis.</li><li>A refund payout rate is stored with an explicit direction and checked against bounds. See <a href="/ahlaan-train-docs/admin/refund-bank-disbursement/">Refund bank disbursement</a>.</li><li>A new manual-transfer instruction replaces the earlier one. See <a href="/ahlaan-train-docs/customer/manual-transfer/">Manual transfer</a>.</li><li>Staff administration moves behind its own permissions. See <a href="/ahlaan-train-docs/admin/roles/">Roles</a>.</li></ul><h2 id="_3-to-9-august-2026" tabindex="-1">3 to 9 August 2026 <a class="header-anchor" href="#_3-to-9-august-2026" aria-label="Permalink to &quot;3 to 9 August 2026&quot;">​</a></h2><ul><li>Manual transfer: one admin-selected destination bank per currency; IDR can be paid by bank transfer; an admin can upload a transfer proof for a customer; manual transfer is no longer offered on a settled invoice. See <a href="/ahlaan-train-docs/customer/manual-transfer/">Manual transfer</a> and <a href="/ahlaan-train-docs/admin/manual-transfer/">Manual transfer (admin)</a>.</li><li>Custom booking capital: editable through <code>COMPLETED</code>, with one status rule for the three capital routes; writes need <code>custom-bookings:write-capital</code>; money fields on admin responses depend on the admin&#39;s role. See <a href="/ahlaan-train-docs/admin/custom-booking/">Custom booking (admin)</a>.</li><li>Custom booking tickets: partial upload and a close that checks it; the money that goes back on a short delivery is recorded, with a reason, an attachment and a per-leg estimate; partial tickets are delivered without waiting for that refund; the ticket is emailed on upload; an uploaded ticket waits until a second admin releases it. See <a href="/ahlaan-train-docs/admin/custom-booking/">Custom booking (admin)</a>.</li><li>The customer invoice block shows the USD amount and the destination bank. See <a href="/ahlaan-train-docs/customer/custom-booking/">Custom booking</a>.</li><li><code>tripClass</code> must be a valid class when creating a custom booking.</li></ul><h2 id="_27-july-to-2-august-2026" tabindex="-1">27 July to 2 August 2026 <a class="header-anchor" href="#_27-july-to-2-august-2026" aria-label="Permalink to &quot;27 July to 2 August 2026&quot;">​</a></h2><ul><li>The customer payment list shows the manual-transfer <code>proofStatus</code>. See <a href="/ahlaan-train-docs/customer/manual-transfer/">Manual transfer</a>.</li><li>Manual transfer needs two approvals: finance checks the funds, booking management approves. See <a href="/ahlaan-train-docs/admin/manual-transfer/">Manual transfer (admin)</a>.</li><li>Admins see more payment detail, and an act-as-customer session can be handed from one admin to another. See <a href="/ahlaan-train-docs/admin/impersonation/">Impersonation</a>.</li><li>Mitra self-registration can be switched off. See <a href="/ahlaan-train-docs/customer/mitra-registration/">Mitra registration</a>.</li></ul><h2 id="_20-to-26-july-2026" tabindex="-1">20 to 26 July 2026 <a class="header-anchor" href="#_20-to-26-july-2026" aria-label="Permalink to &quot;20 to 26 July 2026&quot;">​</a></h2><ul><li>Admin role permissions apply to the admin routes: an admin without the permission gets 403. Unknown permission codes are refused, the user list shows Access Roles, role members are paged, and roles can be given or removed in bulk. See <a href="/ahlaan-train-docs/admin/roles/">Roles</a>.</li><li>The invoice list filters by currency, payment gateway, booking code and the <code>MITRA_REGISTRATION</code> source, takes a search term, and its date range applies to <code>createdAt</code>. List and report query parameters match. See <a href="/ahlaan-train-docs/admin/invoice/">Invoice</a>.</li><li>Admins set group-size and advance-booking limits. See <a href="/ahlaan-train-docs/admin/search-booking-limits/">Search and booking limits</a>.</li></ul><h2 id="_13-to-19-july-2026" tabindex="-1">13 to 19 July 2026 <a class="header-anchor" href="#_13-to-19-july-2026" aria-label="Permalink to &quot;13 to 19 July 2026&quot;">​</a></h2><ul><li>Mitra partner program: a partner can be a user without an organization (a B2C user can be SILVER or GOLD); registration starts with an email OTP and the server assigns the SPK number; an applicant can sign in to see their own application; approval creates the registration invoice; the partnership document is no longer required; partner access needs a numbered registration; the reviewer is shown; NIB and NPWP proofs accept images and PDF. See <a href="/ahlaan-train-docs/customer/mitra-registration/">Mitra registration</a> and <a href="/ahlaan-train-docs/admin/mitra-registrations/">Mitra registrations</a>.</li><li>Invoices carry partner identity and the handling admin, and booking line items show the cabin class of each leg. Invoice detail returns the <code>exchangeRate</code> block, the GOLD effective rate and the cross-currency <code>totalPaid</code>. See <a href="/ahlaan-train-docs/admin/invoice/">Invoice</a>.</li><li>OTA per-passenger prices are rounded up to a whole riyal, and per-flight totals and <code>pricePerAdult</code> follow. See <a href="/ahlaan-train-docs/customer/ota/">OTA</a>.</li><li>The profile and the admin views show the effective pricing tier.</li><li>New in-person payment in SAR at an office, with office locations managed by admins and an admin proof upload. See <a href="/ahlaan-train-docs/customer/in-person-office-payment/">In-person office payment</a> and <a href="/ahlaan-train-docs/admin/office-locations/">Office locations</a>.</li><li>Custom booking: the handling admin&#39;s name is shown to the customer; the minimum group is 5 for GOLD and 10 for other tiers; admins can recompute the capital price. See <a href="/ahlaan-train-docs/customer/custom-booking/">Custom booking</a>.</li><li>Ticket channel route prices return origin and destination codes and names. See <a href="/ahlaan-train-docs/admin/ticket-channels/">Ticket channels</a>.</li><li>Custom OTA search metadata echoes the real passenger counts.</li><li>The Mitra child-to-adult sell price ratio is configurable. See <a href="/ahlaan-train-docs/admin/mitra-pricing-config/">Mitra pricing config</a>.</li></ul><h2 id="_6-to-12-july-2026" tabindex="-1">6 to 12 July 2026 <a class="header-anchor" href="#_6-to-12-july-2026" aria-label="Permalink to &quot;6 to 12 July 2026&quot;">​</a></h2><ul><li>Promo tier prices: a baseline tier, <code>promoTierPrices</code> per caller (all three tiers for a signed-in caller), per-fare-level ECONOMY reducers for silver and gold, and gold BUSINESS markup and tax. See <a href="/ahlaan-train-docs/customer/custom-ota/">Custom OTA</a>.</li><li>A negative reducer acts as a surcharge.</li><li>New pricing tier per user or organization; a B2C user can be GOLD.</li><li>New Mitra self-registration; GOLD approval needs a payment proof and a deposit acknowledgement. See <a href="/ahlaan-train-docs/customer/mitra-registration/">Mitra registration</a>.</li><li>Admins can act as a customer on custom bookings. See <a href="/ahlaan-train-docs/admin/impersonation/">Impersonation</a>.</li><li><strong>Breaking:</strong> creating a custom booking, updating its passengers and cancelling it are for admins and act-as-customer sessions. Passenger update and cancel need a login (the guest email and phone path is gone), and a customer acting alone gets 403. Why: an admin creates and changes custom bookings for the customer. See <a href="/ahlaan-train-docs/customer/custom-booking/">Custom booking</a>.</li></ul><h2 id="_29-june-to-5-july-2026" tabindex="-1">29 June to 5 July 2026 <a class="header-anchor" href="#_29-june-to-5-july-2026" aria-label="Permalink to &quot;29 June to 5 July 2026&quot;">​</a></h2><ul><li><strong>Breaking:</strong> customer custom-booking responses no longer include <code>pricingSnapshot</code>; only admins get it. Why: it holds cost figures meant for staff. See <a href="/ahlaan-train-docs/customer/custom-booking/">Custom booking</a>.</li><li>Promo host sign-in and booking are limited to customers an admin created; a refused sign-in shows a partner-only message.</li><li>Special B2B pricing: BUSINESS rate reducer, directional ECONOMY tiers, and a tiered USD to SAR rate shown in the custom OTA <code>exchangeRate</code> block. A promo-host search without login returns the three tier prices. See <a href="/ahlaan-train-docs/admin/special-custom-b2b-pricing/">Special custom B2B pricing</a>.</li><li>Custom booking responses carry <code>isSpecialB2B</code>, and <code>organizationId</code> is filled in automatically.</li><li>Admin user and organization lists take a search term; a deactivated organization can be activated again; B2C users ignore organization rules. See <a href="/ahlaan-train-docs/admin/organizations/">Organizations</a> and <a href="/ahlaan-train-docs/admin/users/">Users</a>.</li></ul><h2 id="_22-to-28-june-2026" tabindex="-1">22 to 28 June 2026 <a class="header-anchor" href="#_22-to-28-june-2026" aria-label="Permalink to &quot;22 to 28 June 2026&quot;">​</a></h2><ul><li><strong>Breaking:</strong> the refund and organization report routes are served under <code>/api/v1</code>. Why: they answered without the version segment, not at their documented paths. See <a href="/ahlaan-train-docs/customer/refunds/">Refunds</a> and <a href="/ahlaan-train-docs/admin/reports/organization.html">Organization reports</a>.</li><li>Customer refunds are direct-to-bank only (wallet refunds are hidden), bank details are prefilled and can be saved back, and a refund for someone else&#39;s booking answers 404 instead of 400. See <a href="/ahlaan-train-docs/customer/refunds/">Refunds</a>.</li><li>Admin refunds: payouts in currencies other than SAR, a <code>calculate-refund</code> endpoint based on the amount paid, a source filter on the refund list, and the direct-to-bank refund status on the booking list and detail. See <a href="/ahlaan-train-docs/admin/refunds/">Refunds (admin)</a>.</li><li>Admins filter audit logs, payment reports and invoice reports by booking source (<code>STANDARD</code>, <code>BLOCKSEAT</code>, <code>CUSTOM</code>). See <a href="/ahlaan-train-docs/admin/audit-logs/">Audit logs</a>.</li><li>Admin-only supplier cost on invoices (<code>itinTotalFare</code>) and on the booking list and detail (<code>pricing.supplier</code>).</li><li>Ticket downloads check who asks: the owner, their organization, an admin or a verified guest.</li><li>The booking cancellation email no longer mentions refunds.</li><li>New special B2B pricing that admins switch on per organization, with an ECONOMY price cap and automatic fare-tier discovery; admin organization and user views show <code>specialCustomPricingEnabled</code>. See <a href="/ahlaan-train-docs/admin/special-custom-b2b-pricing/">Special custom B2B pricing</a>.</li></ul><h2 id="_15-to-21-june-2026" tabindex="-1">15 to 21 June 2026 <a class="header-anchor" href="#_15-to-21-june-2026" aria-label="Permalink to &quot;15 to 21 June 2026&quot;">​</a></h2><ul><li>New BlockSeat: wholesale bookings for 11 or more passengers through the OTA flow, ECONOMY only, priced from the supplier fare minus a reducer. It has its own frontend host for sign-in, payment redirect and ticket links, and its payment is limited to a configurable list of gateways. See <a href="/ahlaan-train-docs/customer/blockseat-ota/">BlockSeat OTA</a> and <a href="/ahlaan-train-docs/customer/blockseat-bookings/">BlockSeat bookings</a>.</li><li>Admins can refund straight to a bank account, with configurable eligibility (BlockSeat by default). See <a href="/ahlaan-train-docs/admin/refund-bank-disbursement/">Refund bank disbursement</a>.</li><li>Optional email and phone: a blank value is left out, and <code>null</code> clears it.</li><li>Custom markup and tax apply to BUSINESS class in custom OTA and custom booking; the lists are paged, and a FIXED <code>taxRate</code> has no cap. See <a href="/ahlaan-train-docs/admin/custom-markup/">Custom markup</a> and <a href="/ahlaan-train-docs/admin/custom-tax/">Custom tax</a>.</li><li>The admin booking list returns station names and field types that match the wire. See <a href="/ahlaan-train-docs/admin/booking-management/">Booking management (admin)</a>.</li><li>A cross-currency manual transfer settles when an admin confirms it.</li></ul><h2 id="_8-to-14-june-2026" tabindex="-1">8 to 14 June 2026 <a class="header-anchor" href="#_8-to-14-june-2026" aria-label="Permalink to &quot;8 to 14 June 2026&quot;">​</a></h2><ul><li><strong>Breaking:</strong> <code>POST /ota/availability-range</code> and <code>POST /custom-ota/availability-range</code> need a login; an anonymous call gets 401. Why: the calendar view is for signed-in users only. See <a href="/ahlaan-train-docs/customer/ota/availability-range.html">Availability range</a>.</li><li>New <code>POST /custom-ota/availability-range</code>: 7 days, priced like the custom OTA search. See <a href="/ahlaan-train-docs/customer/custom-ota/availability-range.html">Custom OTA availability range</a>.</li><li>Admins set the SAR to USD rate. See <a href="/ahlaan-train-docs/admin/exchange-rate/">Exchange rate</a>.</li><li>Manual transfer for custom bookings in SAR or USD; admins can reopen a payment for a new proof; its expiry is configurable; the payment instruction is sent on generate-payment instead of on confirm. See <a href="/ahlaan-train-docs/customer/manual-transfer/">Manual transfer</a>.</li><li>Custom pricing: the price reducer is shared per passenger by fare ratio, and each passenger&#39;s SAR price is a whole riyal with the total equal to the sum. Custom OTA pricing reads the supplier fare directly and enforces its own seat cap. New flat custom markup and tax settings. See <a href="/ahlaan-train-docs/customer/custom-ota/">Custom OTA</a>.</li><li>The OTA search cache is cleared when a tax rule changes.</li><li>The payment deadline is shown in WhatsApp messages and emails.</li><li>Custom booking manifest: blank passenger rows are dropped, and each passenger can opt in with <code>rememberPassenger</code>. See <a href="/ahlaan-train-docs/customer/custom-manifest/">Custom manifest</a>.</li></ul><h2 id="_1-to-7-june-2026" tabindex="-1">1 to 7 June 2026 <a class="header-anchor" href="#_1-to-7-june-2026" aria-label="Permalink to &quot;1 to 7 June 2026&quot;">​</a></h2><ul><li>Custom OTA prices come from the OTA fare with a price reducer; IDR is floored to whole rupiah and SAR to 2 decimals, and the custom <code>finalPrice</code> to a whole riyal. See <a href="/ahlaan-train-docs/customer/custom-ota/">Custom OTA</a>.</li><li>Custom booking: flight PNR and airline per passenger, also in the admin manifest; the manifest upload confirms the booking; the customer can edit passengers for longer; the Xendit payment expiry is configurable (30 minutes by default); generate-payment reuses an open link; a paid booking goes straight to <code>WAITING_FOR_TICKET</code>; the booking expires with its Xendit payment; a minimum number of seated passengers applies on create. See <a href="/ahlaan-train-docs/customer/custom-booking/">Custom booking</a>.</li><li>Saved passengers take optional airline PNR fields. See <a href="/ahlaan-train-docs/customer/saved-passengers/">Saved passengers</a>.</li><li>Manual transfer is behind a switch.</li><li>New raw OTA low-fare search for the price scraper (API key). See <a href="/ahlaan-train-docs/admin/scraper-search/">Scraper search</a>.</li><li>Partner settlement: partner bookings are invoiced and settled from the bank webhook, an open partner invoice is voided when its booking expires, and the admin invoice report filters by <code>partnerId</code>. See <a href="/ahlaan-train-docs/admin/partners/">Partners</a>.</li><li>A booking whose train has departed can no longer be cancelled.</li></ul><h2 id="_25-to-31-may-2026" tabindex="-1">25 to 31 May 2026 <a class="header-anchor" href="#_25-to-31-may-2026" aria-label="Permalink to &quot;25 to 31 May 2026&quot;">​</a></h2><ul><li>Partner API scopes for OTA orders: read, write, cancel, ticket and modify. See <a href="/ahlaan-train-docs/admin/partners/">Partners</a>.</li><li>B2B pricing no longer estimates child and infant prices.</li></ul><h2 id="_18-to-24-may-2026" tabindex="-1">18 to 24 May 2026 <a class="header-anchor" href="#_18-to-24-may-2026" aria-label="Permalink to &quot;18 to 24 May 2026&quot;">​</a></h2><ul><li>Custom booking emails the customer to pay when the booking becomes <code>CONFIRMED</code>.</li><li>Partners: <code>/me</code> portal routes, the admin booking list filters by <code>partnerId</code>, a partner audit log, and the currencies each partner may use. See <a href="/ahlaan-train-docs/admin/partners/">Partners</a>.</li><li><code>POST /ota/bookings/:id/cancel</code> returns the booking response instead of the raw record. See <a href="/ahlaan-train-docs/customer/booking-management/">Booking management</a>.</li></ul><h2 id="_11-to-17-may-2026" tabindex="-1">11 to 17 May 2026 <a class="header-anchor" href="#_11-to-17-may-2026" aria-label="Permalink to &quot;11 to 17 May 2026&quot;">​</a></h2><ul><li>OTA 400 errors share one envelope with a machine-readable code (<code>PASSENGER_COUNT_MISMATCH</code>, <code>INPUT_VALIDATION</code>, <code>UNCODED</code>) and, for input errors, the failing fields in <code>context.fields</code>. The added fields keep older clients working. See <a href="/ahlaan-train-docs/customer/ota/errors.html">OTA errors</a>.</li><li><code>POST /ota/book/calculate</code> returns the real tax and flight information, as optional fields.</li><li>New partner channel: admins manage partner credentials, and partners sign in through a handoff with a partner-scoped token. See <a href="/ahlaan-train-docs/admin/partners/">Partners</a>.</li></ul><h2 id="_4-to-10-may-2026" tabindex="-1">4 to 10 May 2026 <a class="header-anchor" href="#_4-to-10-may-2026" aria-label="Permalink to &quot;4 to 10 May 2026&quot;">​</a></h2><ul><li>Passenger and contact fields check email and international phone formats.</li><li>Admins see why a booking is stuck, with contact details, a follow-up trail and the booking status history. See <a href="/ahlaan-train-docs/admin/booking-management/">Booking management (admin)</a>.</li><li>Custom booking capital comes from the ticket channel route price at <code>CONFIRMED</code>; the admin manifest can be a configurable CSV. See <a href="/ahlaan-train-docs/admin/custom-booking/">Custom booking (admin)</a>.</li><li>Audit logs filter by booking or custom booking. See <a href="/ahlaan-train-docs/admin/audit-logs/">Audit logs</a>.</li></ul><h2 id="_27-april-to-3-may-2026" tabindex="-1">27 April to 3 May 2026 <a class="header-anchor" href="#_27-april-to-3-may-2026" aria-label="Permalink to &quot;27 April to 3 May 2026&quot;">​</a></h2><ul><li>New Sign in with Apple, next to Google. See <a href="/ahlaan-train-docs/customer/register-login/">Register and login</a>.</li><li>The public API is limited to OTA routes, adds a routes list behind the <code>ota:routes</code> scope, and API keys get a scope catalog and a <code>PATCH</code> route. See <a href="/ahlaan-train-docs/customer/public-api-keys/">Public API keys</a>.</li><li>A B2B application&#39;s <code>companyEmail</code> must be unique; a duplicate answers 409. See <a href="/ahlaan-train-docs/customer/b2b-registration/">B2B registration</a>.</li><li>Admin organization <code>GET</code>, <code>POST</code> and <code>PATCH /:id</code> return the same detail shape. See <a href="/ahlaan-train-docs/admin/organizations/">Organizations</a>.</li><li>Payment and invoice reports filter by source. See <a href="/ahlaan-train-docs/admin/reports/">Reports</a>.</li><li>Payments carry <code>amountSAR</code>.</li></ul><h2 id="_20-to-26-april-2026" tabindex="-1">20 to 26 April 2026 <a class="header-anchor" href="#_20-to-26-april-2026" aria-label="Permalink to &quot;20 to 26 April 2026&quot;">​</a></h2><ul><li>New public API: API-key endpoints for OTA search and price calculation, with an API reference, per-key rate limits and self-service key management. See <a href="/ahlaan-train-docs/customer/public-api-keys/">Public API keys</a> and <a href="/ahlaan-train-docs/admin/public-api-access/">Public API access</a>.</li><li>New manual bank transfer payment for custom booking invoices, with an optional unique-amount suffix and proof review on the admin invoice and custom-booking detail. See <a href="/ahlaan-train-docs/customer/manual-transfer/">Manual transfer</a>.</li><li>Custom booking: admins upload several tickets, the manifest is sent to admins over WhatsApp, and the capital price is stored with an admin edit route. See <a href="/ahlaan-train-docs/admin/custom-booking/">Custom booking (admin)</a>.</li><li>Admin mark-paid writes the payment totals and moves the booking on. The invoice list filters by source. See <a href="/ahlaan-train-docs/admin/invoice/">Invoice</a>.</li><li>The admin booking list returns <code>departureDateTime</code> and <code>returnDateTime</code>.</li><li>Railway stations get their own admin routes. See <a href="/ahlaan-train-docs/admin/railway-stations/">Railway stations</a>.</li></ul><h2 id="_13-to-19-april-2026" tabindex="-1">13 to 19 April 2026 <a class="header-anchor" href="#_13-to-19-april-2026" aria-label="Permalink to &quot;13 to 19 April 2026&quot;">​</a></h2><ul><li>Custom booking: ticket fulfilment by a ticket provider, admin list and detail, the exchange rate fixed at create, guest manifest upload and download, the booking completes on ticket upload, and admins get a WhatsApp message when a manifest arrives. See <a href="/ahlaan-train-docs/customer/custom-booking/">Custom booking</a> and <a href="/ahlaan-train-docs/customer/custom-manifest/">Custom manifest</a>.</li><li>Google sign-in works on the custom OTA domain. See <a href="/ahlaan-train-docs/customer/register-login/">Register and login</a>.</li><li>Admin invoices say whether they belong to a booking or a custom booking. See <a href="/ahlaan-train-docs/admin/invoice/">Invoice</a>.</li></ul><h2 id="_6-to-12-april-2026" tabindex="-1">6 to 12 April 2026 <a class="header-anchor" href="#_6-to-12-april-2026" aria-label="Permalink to &quot;6 to 12 April 2026&quot;">​</a></h2><ul><li>New admin modules: scraper prices, custom route prices, custom bookings and custom manifests. See <a href="/ahlaan-train-docs/admin/scraper-price/">Scraper price</a>, <a href="/ahlaan-train-docs/admin/custom-route-price/">Custom route price</a> and <a href="/ahlaan-train-docs/admin/custom-booking/">Custom booking (admin)</a>.</li><li>Pricing rules: <code>targetClass</code>, <code>target</code> and <code>type</code> can be updated; B2B markup applies per cabin class in search; per-leg rules apply to the return flight of a <code>ROUND_TRIP</code>; a tariff is the final price, with no markup or tax on top. See <a href="/ahlaan-train-docs/admin/pricing/">Pricing</a> and <a href="/ahlaan-train-docs/admin/tariff/">Tariff</a>.</li></ul><h2 id="_30-march-to-5-april-2026" tabindex="-1">30 March to 5 April 2026 <a class="header-anchor" href="#_30-march-to-5-april-2026" aria-label="Permalink to &quot;30 March to 5 April 2026&quot;">​</a></h2><ul><li>Request fields have length and array-size limits.</li><li>An old exchange rate no longer blocks search.</li><li>Markup and tax rules can depend on passenger count, and B2B prices are no longer marked up twice. See <a href="/ahlaan-train-docs/admin/pricing/">Pricing</a>.</li></ul><h2 id="_23-to-29-march-2026" tabindex="-1">23 to 29 March 2026 <a class="header-anchor" href="#_23-to-29-march-2026" aria-label="Permalink to &quot;23 to 29 March 2026&quot;">​</a></h2><ul><li>USD in OTA search, booking, wallet and <code>ptcFareBreakdown</code>, and USD Xendit payments for bookings. Xendit bank transfer and invoice are IDR only.</li><li>User details: nationality default, address fields, and <code>documentType</code> renamed to <code>idType</code>. The profile response merges <code>userDetails</code> into <code>contactPerson</code>. See <a href="/ahlaan-train-docs/customer/user-details/">User details</a>.</li><li>The exchange rate uses the bank&#39;s TT Counter rates.</li></ul><h2 id="_16-to-22-march-2026" tabindex="-1">16 to 22 March 2026 <a class="header-anchor" href="#_16-to-22-march-2026" aria-label="Permalink to &quot;16 to 22 March 2026&quot;">​</a></h2><ul><li>New Google sign-in: the token is set in an httpOnly cookie, and mobile apps exchange a Google token at their own endpoint. See <a href="/ahlaan-train-docs/customer/register-login/">Register and login</a>.</li><li>The ticket email attaches a PDF for one ticket and a ZIP for several. See <a href="/ahlaan-train-docs/customer/tickets-email/">Tickets email</a>.</li><li>B2B applications can be approved automatically, and B2B users can book as guests.</li></ul><h2 id="_9-to-15-march-2026" tabindex="-1">9 to 15 March 2026 <a class="header-anchor" href="#_9-to-15-march-2026" aria-label="Permalink to &quot;9 to 15 March 2026&quot;">​</a></h2><ul><li>Cancellation refunds: several refunds per booking, a booking with every segment cancelled is cancelled, and bookings carry <code>flightStatus</code>.</li><li>Segment cancellation (modification type 10) is turned off and fails validation.</li><li>Bookings store a <code>contactPerson</code>.</li><li>GROUP bookings: passengers are updated with an optional <code>rememberPassengers</code>, passenger age is checked from the date of birth, and a confirmation email carries <code>updateTravellersTimeLimit</code>. See <a href="/ahlaan-train-docs/customer/update-group-booking-passengers/">Update group booking passengers</a>.</li><li>New emails for booking confirmed, cancelled and ticketed.</li></ul><h2 id="_2-to-8-march-2026" tabindex="-1">2 to 8 March 2026 <a class="header-anchor" href="#_2-to-8-march-2026" aria-label="Permalink to &quot;2 to 8 March 2026&quot;">​</a></h2><ul><li>An infant is linked to its adult (<code>attendantRph</code>) automatically; only supported modification types are accepted; cancelling a cancelled booking no longer fails.</li></ul><h2 id="_23-february-to-1-march-2026" tabindex="-1">23 February to 1 March 2026 <a class="header-anchor" href="#_23-february-to-1-march-2026" aria-label="Permalink to &quot;23 February to 1 March 2026&quot;">​</a></h2><ul><li>New <code>EXPIRED</code> status for unpaid bookings past <code>confirmationTimeLimit</code>, with a booking status history.</li><li><code>PATCH /profile/contact-person</code> replaces the old profile update and takes <code>middleName</code>. See <a href="/ahlaan-train-docs/customer/user-details/">User details</a>.</li><li>The booking detail shows prices per leg, and the trip summary carries <code>outboundFlight</code> and <code>returnFlight</code>.</li><li>The search response adds camelCase fields; the snake_case fields are deprecated. See <a href="/ahlaan-train-docs/customer/search-train-b2c/">Search (B2C)</a>.</li><li>Phone numbers are normalized; passenger names cannot change after ticketing.</li><li><code>POST /ota/book/calculate</code> rounds IDR correctly.</li></ul><h2 id="_16-to-22-february-2026" tabindex="-1">16 to 22 February 2026 <a class="header-anchor" href="#_16-to-22-february-2026" aria-label="Permalink to &quot;16 to 22 February 2026&quot;">​</a></h2><ul><li>New <code>POST /ota/availability-range</code>, with <code>pricePerAdult</code> and <code>isB2B</code>. See <a href="/ahlaan-train-docs/customer/ota/availability-range.html">Availability range</a>.</li><li>A booking of 11 or more passengers is a GROUP booking.</li><li>New financial reports for admins and B2B users, and admin booking reports. See <a href="/ahlaan-train-docs/admin/reports/">Reports</a>.</li><li>Guests can read their invoice.</li><li>Times in responses are in Arabia Standard Time.</li><li>Email and phone changes take two steps.</li><li><code>ptcFareBreakdown</code> in price calculation and booking detail.</li><li>Admins manage notifications. See <a href="/ahlaan-train-docs/admin/notifications/">Notifications</a>.</li></ul><h2 id="_9-to-15-february-2026" tabindex="-1">9 to 15 February 2026 <a class="header-anchor" href="#_9-to-15-february-2026" aria-label="Permalink to &quot;9 to 15 February 2026&quot;">​</a></h2><ul><li>New refunds with a 7-day cancellation rule; bookings carry <code>modifyDeniedReason</code>.</li><li>Bookings carry <code>canModifyPassengerName</code> and <code>canModifyPassengerInfo</code>.</li><li>A booking not paid by <code>confirmationTimeLimit</code> expires.</li><li>Admins get customer-support and stuck-booking routes.</li></ul><h2 id="_2-to-8-february-2026" tabindex="-1">2 to 8 February 2026 <a class="header-anchor" href="#_2-to-8-february-2026" aria-label="Permalink to &quot;2 to 8 February 2026&quot;">​</a></h2><ul><li>B2B GROUP bookings priced per passenger type, and B2B prices match between <code>/ota/search</code> and <code>/ota/book/calculate</code>. See <a href="/ahlaan-train-docs/customer/search-train-b2b/">Search (B2B)</a>.</li><li>Wallets are SAR only; the currency field is gone.</li><li>A B2B application creates the user account.</li><li>Booking responses carry station names, <code>serviceClass</code>, <code>serviceClassName</code>, <code>flightSegments</code>, <code>fareReference</code> and invoice details.</li><li>Ticket download returns a ZIP.</li><li>Admins list bookings and bank details, reject bank details, and resend cancellation and confirmation emails.</li></ul><h2 id="_26-january-to-1-february-2026" tabindex="-1">26 January to 1 February 2026 <a class="header-anchor" href="#_26-january-to-1-february-2026" aria-label="Permalink to &quot;26 January to 1 February 2026&quot;">​</a></h2><ul><li>Search applies markup and tax, and returns <code>originalFinalPrice</code> for a struck-through price. B2C bookings need a contact person.</li><li>Admins set fare preferences, reconcile payments and generate invoices. See <a href="/ahlaan-train-docs/admin/fare-preference/">Fare preference</a>.</li><li>Notifications for payment, wallet and B2B events.</li><li>New wallet top-up price calculation.</li><li>Admins manage WhatsApp devices. See <a href="/ahlaan-train-docs/admin/whatsapp/">WhatsApp</a>.</li><li>The profile returns <code>organizationId</code> and <code>b2bApplicationStatus</code>; files can be downloaded with a token. See <a href="/ahlaan-train-docs/storage/">Storage</a>.</li><li>This documentation site is set up.</li></ul><h2 id="_19-to-25-january-2026" tabindex="-1">19 to 25 January 2026 <a class="header-anchor" href="#_19-to-25-january-2026" aria-label="Permalink to &quot;19 to 25 January 2026&quot;">​</a></h2><ul><li>New refresh tokens, and OTP requests are rate limited.</li><li>New tax settings, tariffs and locations, and payment gateway fees. See <a href="/ahlaan-train-docs/admin/tax/">Tax</a>, <a href="/ahlaan-train-docs/admin/tariff/">Tariff</a> and <a href="/ahlaan-train-docs/admin/payment-gateway-fees/">Payment gateway fees</a>.</li><li>Saved passengers. See <a href="/ahlaan-train-docs/customer/saved-passengers/">Saved passengers</a>.</li><li>Wallets: top-up, withdrawal and an admin overview. See <a href="/ahlaan-train-docs/admin/wallet/">Wallet</a>.</li><li>Admin dashboard summary and bank list. See <a href="/ahlaan-train-docs/admin/banks/">Banks</a>.</li><li>B2C prices in search.</li></ul><h2 id="_12-to-18-january-2026" tabindex="-1">12 to 18 January 2026 <a class="header-anchor" href="#_12-to-18-january-2026" aria-label="Permalink to &quot;12 to 18 January 2026&quot;">​</a></h2><ul><li>New <code>POST /ota/book/calculate</code> price preview, seat availability check and Xendit invoice payments.</li><li>Admins confirm a payment by hand.</li><li>A guest&#39;s first booking creates a B2C account.</li></ul><h2 id="_5-to-11-january-2026" tabindex="-1">5 to 11 January 2026 <a class="header-anchor" href="#_5-to-11-january-2026" aria-label="Permalink to &quot;5 to 11 January 2026&quot;">​</a></h2><ul><li>New file storage. See <a href="/ahlaan-train-docs/storage/">Storage</a>.</li><li>B2B and B2C pricing rules, and peak-hour pricing. See <a href="/ahlaan-train-docs/admin/pricing/">Pricing</a>.</li><li>Calendar availability and email resend routes.</li><li>Admin roles with an audit log. See <a href="/ahlaan-train-docs/admin/roles/">Roles</a> and <a href="/ahlaan-train-docs/admin/audit-logs/">Audit logs</a>.</li><li>Admin password reset, email and phone change, and <code>isPhoneConfirmed</code> on the profile. See <a href="/ahlaan-train-docs/admin/password-reset/">Password reset</a>.</li></ul><h2 id="_29-december-2025-to-4-january-2026" tabindex="-1">29 December 2025 to 4 January 2026 <a class="header-anchor" href="#_29-december-2025-to-4-january-2026" aria-label="Permalink to &quot;29 December 2025 to 4 January 2026&quot;">​</a></h2><ul><li>Routes are versioned under <code>/api/v1</code>.</li><li>Email confirmation, OTP sign-in and WhatsApp messages.</li><li>Train search by adults, children and infants; regular and group booking; booking changes.</li><li>Xendit payments with webhooks, wallets and invoices.</li></ul><h2 id="_22-to-28-december-2025" tabindex="-1">22 to 28 December 2025 <a class="header-anchor" href="#_22-to-28-december-2025" aria-label="Permalink to &quot;22 to 28 December 2025&quot;">​</a></h2><ul><li>First release.</li></ul>',91)])])}const p=a(o,[["render",r]]);export{m as __pageData,p as default};
